package com.Hecate.puppet.pixel;

import com.Hecate.puppet.volume.*;
import com.google.gson.Gson;
import com.jme3.math.*;
import com.jme3.scene.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.*;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

final class BlenderPixelImportTest {
    @TempDir Path temp;
    static Mesh square(){Mesh mesh=new Mesh();mesh.setBuffer(VertexBuffer.Type.Position,3,new float[]{-.5f,-.5f,0,.5f,-.5f,0,.5f,.5f,0,-.5f,.5f,0});mesh.setBuffer(VertexBuffer.Type.Index,3,new int[]{0,1,2,0,2,3});mesh.updateBound();return mesh;}
    @Test void oneMetreSquareHasExactly25By25OccupiedPixels(){var node=new Node("Square");node.attachChild(new Geometry("Mesh",square()));var parts=BlenderPixelImporter.fromScene(node);var d=parts.get(0).definition();assertEquals(25,d.getPixelsPerUnit());assertEquals(25,d.getWidthPx());assertEquals(25,d.getHeightPx());var atlas=PixelAtlasBaker.bake(d);int minX=999,minY=999,maxX=-1,maxY=-1,count=0;for(int y=0;y<atlas.size();y++)for(int x=0;x<atlas.size();x++)if(atlas.occupied(20,x,y)){count++;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}assertEquals(25,maxX-minX+1);assertEquals(25,maxY-minY+1);assertEquals(25*25,count);atlas.dispose();}
    @Test void originAndParentArePreservedAndObjectScaleIsBakedOnlyOnce(){Node scene=new Node("Scene"),body=new Node("Body"),arm=new Node("Arm");scene.attachChild(body);body.attachChild(new Geometry("bodyMesh",square()));body.setLocalTranslation(2,3,4);body.attachChild(arm);arm.setLocalTranslation(.5f,1,0);arm.setLocalScale(2);arm.attachChild(new Geometry("armMesh",square()));var parts=BlenderPixelImporter.fromScene(scene);assertEquals(2,parts.size());assertEquals(0,parts.get(1).parent());assertEquals(new Vector3f(2,3,4),parts.get(0).position());assertEquals(new Vector3f(.5f,1,0),parts.get(1).position());assertEquals(50,parts.get(1).definition().getWidthPx());}
    @Test void importedGeometrySurvivesSaveWithoutOriginalFile(){Node scene=new Node("Object");scene.attachChild(new Geometry("plane",square()));var d=BlenderPixelImporter.fromScene(scene).get(0).definition();String json=new Gson().toJson(d);VolumeDefinition restored=new Gson().fromJson(json,VolumeDefinition.class);assertEquals(PixelAtlasBaker.key(d),PixelAtlasBaker.key(restored));assertEquals(2,VolumeMeshFactory.create(restored).getTriangleCount());assertEquals(25,restored.getPixelsPerUnit());}
    @Test void realGlbLoaderKeepsMetreDimensions()throws Exception{Path path=temp.resolve("one-metre-square.glb");writeSquareGlb(path);var parts=BlenderPixelImporter.load(path);assertEquals(1,parts.size());assertEquals(25,parts.get(0).definition().getWidthPx());assertEquals(25,parts.get(0).definition().getHeightPx());assertEquals("Square",parts.get(0).name());}
    @Test void defaultWindowAndOddByEvenRectangleUseExactIntegerDimensions(){
        Node node=new Node("Rectangle");node.setLocalScale(1,2,1);node.attachChild(new Geometry("Mesh",square()));var d=BlenderPixelImporter.fromScene(node).get(0).definition();assertEquals(25,d.getStrip3D().getSampleWidth());assertEquals(50,d.getStrip3D().getFrameHeight());var atlas=PixelAtlasBaker.bake(d);assertFootprint(atlas,20,25,50);atlas.dispose();
    }
    @Test void oddSquareCoverageHasNoExtraBoundaryRowAndIsIndependentOfWinding(){
        for(boolean reversed:new boolean[]{false,true}){Mesh mesh=square();if(reversed)mesh.setBuffer(VertexBuffer.Type.Index,3,new int[]{2,1,0,3,2,0});Node node=new Node("Square");node.attachChild(new Geometry("Mesh",mesh));var d=BlenderPixelImporter.fromScene(node).get(0).definition();assertEquals(25,d.getStrip3D().getSampleWidth());assertEquals(25,d.getStrip3D().getFrameHeight());var atlas=PixelAtlasBaker.bake(d);assertFootprint(atlas,20,25,25);assertFootprint(atlas,30,25,25);atlas.dispose();}
    }
    @Test void oldPixelSaveUpgradesOnceWithoutStretchingSourceOrChangingArtwork(){
        Node node=new Node("Square");node.attachChild(new Geometry("Mesh",square()));var current=BlenderPixelImporter.fromScene(node).get(0).definition();var gson=new Gson();var json=new com.google.gson.JsonParser().parse(gson.toJson(current)).getAsJsonObject();json.addProperty("pixelsPerUnit",24);json.addProperty("widthPx",24);json.addProperty("heightPx",24);var mesh=json.getAsJsonObject("importedMesh");mesh.addProperty("widthPx",24);mesh.addProperty("heightPx",24);var old=gson.fromJson(json,VolumeDefinition.class);old.getStrip3D().setFrameSize(24,24);old.getStrip3D().layer(Strip3DDefinition.Surface.SIDE).setColorPath("hand-painted.png");old.getBakedPixels().setPalette(java.util.List.of(new BakedPixelDefinition.PaletteEntry("皮肤",0xffffff,0xabcdef)));int n=PixelAtlasBaker.size(old);boolean[] mask=new boolean[n*n];mask[0]=true;old.getBakedPixels().setEdit(20,new BakedPixelDefinition.MaskEdit(n,mask,PixelAtlasBaker.key(old).replace("pixel-v2/","pixel-v1/")));
        PixelMetrics.normalize(old);assertEquals(25,old.getPixelsPerUnit());assertEquals(25,old.getWidthPx());assertEquals(25,old.getImportedMesh().widthPx());assertEquals(25,old.getStrip3D().getFrameWidth());assertEquals("hand-painted.png",old.getStrip3D().layer(Strip3DDefinition.Surface.SIDE).getColorPath());assertEquals(0xffabcdef,old.getBakedPixels().recolor(0xffffffff));assertTrue(old.getBakedPixels().getEdit(20).mask()[0]);assertEquals(1,old.getBakedPixels().staleEdits(PixelAtlasBaker.key(old)));var source=old.getImportedMesh();PixelMetrics.normalize(old);assertSame(source,old.getImportedMesh());var actual=VolumeMeshFactory.create(old);Vector3f a=new Vector3f(),b=new Vector3f(),c=new Vector3f();actual.getTriangle(0,a,b,c);assertEquals(-.5f,a.x,.00001f);assertEquals(.5f,b.x,.00001f);var atlas=PixelAtlasBaker.bake(old);assertFootprint(atlas,20,25,25);atlas.dispose();var legacy=new VolumeDefinition();PixelMetrics.normalize(legacy);assertEquals(32,legacy.getPixelsPerUnit());
    }
    private static void assertFootprint(PixelAtlas atlas,int view,int width,int height){int minX=atlas.size(),minY=atlas.size(),maxX=-1,maxY=-1,count=0;for(int y=0;y<atlas.size();y++)for(int x=0;x<atlas.size();x++)if(atlas.occupied(view,x,y)){count++;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}assertEquals(width,maxX-minX+1);assertEquals(height,maxY-minY+1);assertEquals(width*height,count);}
    @Test void completePuppetPackagePreservesSourceMeshAndPerViewEdits()throws Exception{
        Node object=new Node("Square");object.attachChild(new Geometry("Mesh",square()));var d=BlenderPixelImporter.fromScene(object).get(0).definition();int size=PixelAtlasBaker.size(d);boolean[] edit=new boolean[size*size];java.util.Arrays.fill(edit,true);edit[size*size/2]=false;d.getBakedPixels().setEdit(20,new BakedPixelDefinition.MaskEdit(size,edit,PixelAtlasBaker.key(d)));
        var root=new com.Hecate.puppet.core.Bone("Root");var rootData=new VolumeDefinition();rootData.setSkeletonOnly(true);root.setVolumeDefinition(rootData);var bone=new com.Hecate.puppet.core.Bone("Square");bone.setVolumeDefinition(d);root.addChild(bone);var skeleton=new com.Hecate.puppet.core.Skeleton("Imported");skeleton.setRootBone(root);
        var app=new com.jme3.app.SimpleApplication(){public void simpleInitApp(){}};var renderer=new com.Hecate.puppet.core.PuppetRenderer(app,skeleton);Path file=temp.resolve("imported.puppet");com.Hecate.puppet.config.PuppetPackageIO.savePackage(skeleton,renderer,file.toString());var config=com.Hecate.puppet.config.PuppetPackageIO.readPackageConfig(file.toString());var restored=config.getBones().stream().filter(b->b.getName().equals("Square")).findFirst().orElseThrow().getVolumeDefinition();assertEquals(PixelAtlasBaker.key(d),PixelAtlasBaker.key(restored));assertArrayEquals(edit,restored.getBakedPixels().getEdit(20).mask());assertTrue(config.getBones().stream().filter(b->b.getName().equals("Root")).findFirst().orElseThrow().getVolumeDefinition().isSkeletonOnly());
    }
    static void writeSquareGlb(Path path)throws Exception{
        String json="""
            {"asset":{"version":"2.0"},"scene":0,"scenes":[{"nodes":[0]}],"nodes":[{"name":"Square","mesh":0}],"meshes":[{"primitives":[{"attributes":{"POSITION":0},"indices":1}]}],"buffers":[{"byteLength":60}],"bufferViews":[{"buffer":0,"byteOffset":0,"byteLength":48},{"buffer":0,"byteOffset":48,"byteLength":12}],"accessors":[{"bufferView":0,"componentType":5126,"count":4,"type":"VEC3","min":[-0.5,-0.5,0],"max":[0.5,0.5,0]},{"bufferView":1,"componentType":5123,"count":6,"type":"SCALAR"}]}
            """;
        byte[] text=json.getBytes(java.nio.charset.StandardCharsets.UTF_8);int length=(text.length+3)/4*4;ByteBuffer glb=ByteBuffer.allocate(12+8+length+8+60).order(ByteOrder.LITTLE_ENDIAN);glb.putInt(0x46546c67).putInt(2).putInt(glb.capacity()).putInt(length).putInt(0x4e4f534a).put(text);while(glb.position()<20+length)glb.put((byte)32);glb.putInt(60).putInt(0x004e4942);for(float v:new float[]{-.5f,-.5f,0,.5f,-.5f,0,.5f,.5f,0,-.5f,.5f,0})glb.putFloat(v);for(short v:new short[]{0,1,2,0,2,3})glb.putShort(v);Files.write(path,glb.array());
    }
}
